import pathlib,json,html
out=pathlib.Path(__file__).resolve().parent;ledger=json.loads((out/'overload-findings.json').read_text());s=json.loads((out/'summary.json').read_text());p=json.loads((out/'provenance.json').read_text());pins=json.loads((out/'pins.json').read_text())
def esc(x):return html.escape(str(x),quote=False).replace('|','\\|').replace('\n','<br>')
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |',*['| '+' | '.join(esc(x) for x in r)+' |' for r in rows]])+'\n'
def counts(kind):
 c=s['categories'][kind];rows=[]
 for name,v in c['functions'].items():
  handoff=v['handoff'];check='not specified' if handoff is None else ('matches first-stop units' if handoff==v['first_stop_units'] else 'first-stop count corrected')
  rows.append([name,v['observations'],v['raw'],v['distinct'],v['first_stop_units'],'—' if handoff is None else handoff,check])
 t=c['totals'];rows.append(['TOTAL',t['observations'],t['raw'],t['distinct'],t['first_stop_units'],c['handoff_total'],'matches first-stop total' if t['first_stop_units']==c['handoff_total'] else 'first-stop total corrected'])
 return table(['Function','Observations','Raw unique','Distinct','First-stop units','Handoff','Check'],rows)
def details(kind):
 lines=['### Complete '+kind+' inventories','', 'Each raw row is one complete raw identity; each distinct row is one outermost-access/reason identity. Locations are relative to the frozen adapted tree. Full diagnostic text, source hashes and observation-to-identity references are in `overload-findings.json`. Distinct offsets below are zero-based UTF-8 byte offsets.','']
 for fn in s['categories'][kind]['present_functions']:
  lines+=['#### '+fn,'']
  for view in ['raw','distinct']:
   rows=[]
   for entry in ledger[kind][view]:
    if entry['function']!=fn:continue
    f=entry['finding'];identity=entry['identity'];where=f['where'].removeprefix('/workspace/orm-adapted/')
    location=where if view=='raw' else identity[0][0]+':byte '+str(identity[0][2])
    units=sorted({ledger[kind]['observations'][i]['unit_name']+' @ '+ledger[kind]['observations'][i]['finding']['unit'].removeprefix('/workspace/orm-adapted/') for i in entry['observations']})
    rows.append([location,f['reason'],len(entry['observations']),'; '.join(units)])
   lines += [view.capitalize()+' identities:', '',table(['Location','Exact reason','Observations','Attempting units'],rows),'']
 return '\n'.join(lines)
r=s['categories']['result'];a=s['categories']['parameter'];comparison=pins['comparison']
lines=['# Final main overload-result census','',f"Measured **adamic main `{s['main']}`**, fetched and frozen at the start of this run. No pair or scratch composition is used. This commit holds only this census directory.",'','The landed step 2, step 2b, step 3 and view-entry-fix commits are all verified ancestors of the measured main tip:','',table(['Change','Landed commit'],[[name,sha] for name,sha in p['landed'].items()]),'','## Counting definitions','','Every observation whose exact `reason` starts with `overload N of <function> result` or `overload N of <function> parameter` is included, in every phase and from every attempting unit. `N` is numeric and the function is the diagnostic’s function-name token; `type parameter` reasons are not silently counted as `parameter` reasons.','','The four columns distinguish different questions: **observations** retain repeated diagnostics from different attempting units; **raw unique** uses the prior census meter identity `(kind, source identity, reason, text)`; **distinct** uses source path, source SHA-256, outermost contiguous property/element access start and exact reason; **first-stop units** counts units whose first lowering/deferred finding matches the prefix. Raw and distinct normalization use main’s unmodified `stage3/census/pair/normalize.cjs`; no comparison or paired delta is performed.','','All matching observations, full reason/text, phase, unit names/locations, and every raw/distinct representative and its observation references are in [overload-findings.json](overload-findings.json). The stock normalization request and identities are retained separately.','','## 1. Overload-result findings','',counts('result'),f"The handoff's 45 becomes **{r['totals']['first_stop_units']}** per-unit result first stops. All 11 listed per-function counts are confirmed; the additional **getPathComponents=11** accounts for the difference. Its exact reason is `overload 1 of getPathComponents result PathPathComponents cannot be served by implementation result string[]` at `src/compiler/path.ts:492:1`.",'',f"Observed result-prefix functions: **{len(r['present_functions'])}**. Listed but absent: **{', '.join(r['listed_but_absent']) or 'none'}**. Present but not in the handoff: **{', '.join(r['unlisted_present']) or 'none'}**.",'',details('result')]
expected_match=not r['unlisted_present'] and not r['listed_but_absent'] and all(v['handoff']==v['first_stop_units'] for v in r['functions'].values())
if expected_match:lines+=['Every listed handoff count is confirmed **as a per-unit first-stop count**. It must not be confused with the deduplicated raw or distinct finding count.']
else:
 corrections=[f"{name}: handoff {v['handoff']}, measured first-stop units {v['first_stop_units']}" for name,v in r['functions'].items() if v['handoff'] is not None and v['handoff']!=v['first_stop_units']]
 lines+=['Handoff first-stop corrections: '+('; '.join(corrections) or 'No count correction among listed functions; presence differences are named above.')]
lines+=['','## 2. Overload-parameter findings','',counts('parameter'),f"Observed parameter-prefix functions: **{len(a['present_functions'])}**. Handoff total 27 versus measured **{a['totals']['first_stop_units']} first-stop units**, **{a['totals']['observations']} observations**, **{a['totals']['raw']} raw unique findings**, and **{a['totals']['distinct']} distinct findings**.",'',details('parameter'),'The table includes every observed function, not only the five visitor functions mentioned in the handoff. The explicit visitEachChild=6 and visitParameterList=3 expectations are checked individually; other per-function expectations were not specified.','','## 3. First-stop comparison','',table(['Measure','78933e52 composition head','Current main','Change'],[['Overload-result prefix first-stop units',comparison['overload_result_first_stops'],r['totals']['first_stop_units'],r['totals']['first_stop_units']-comparison['overload_result_first_stops']],['Units with no first lowering/deferred stop',comparison['no_first_stop_units'],s['no_first_stop_units'],s['no_first_stop_units']-comparison['no_first_stop_units']]]),f"The prior canonical `cannot be served by implementation result` first-stop definition counts **{s['canonical_overload_result_first_stops']}** on current main. A unit with no first stop is not proof of complete compilation.",'',table(['Current-main coverage','Count'],[['Resolved source files',len(s['header']['sources'])],['Checker diagnostics',0],['Units',s['units']],['Attempted units',s['attempted']],['Units with no first stop',s['no_first_stop_units']]]),f"The comparison is numerical, against the previous report’s 45 and 3,187. Adapted input manifests match: **{p['input_matches_prior']}**; changed input files: **{p['changed_input_files']}**. Differences are retained in [input-difference-from-78933e52.json](input-difference-from-78933e52.json). No old stream is reused and no paired regression claim is made.",'','## Method and validation','','This is the same stock **first-error latent entry census** as `stage3/census/overload-phantom-78933e52`: `LATENT_FULL=0`, `LATENT_ASSERT_NO_OUTPUT=1`, rooted at the adapted `src/tsc/tsc.ts`. The compiler overlay is built from the measured main tree itself with its own `make_overlay.py` and `entry_overlay.py`, exact recursive submodule pins, and source-generated adaptation from its own `apply.sh`. The TypeScript source pin, complete adapted-source hashes, overlay maps and executable hashes are retained.','','Ordinary Load and Lower remain disabled. No backend or usable IR is produced. Each of eight disjoint attempted-unit shards keeps the full project and registration graph. Shards 0 and 1 run complete refusal scans, which must agree exactly; shards 2–7 omit only repeated scans. Two shards run concurrently with `GOMEMLIMIT=3GiB`. Eligibility and generic deferral remain unchanged. Deferred/skipped records deduplicate, and generic call witnesses union under the original Go order and five-witness cap. Each attempted unit appears once. Process-scoped relation/cache reports stay separate, never summed; any overflow or global finding stops composition.','','Both binary variants pass the unsplit-versus-sharded fixture, including a real overloaded callback-value stop and cross-shard generic witnesses. The existing latent audit and all 20 normalization/pair-tool tests pass; the tests do not constitute a paired census. A stock-parser inventory independently checks every top-level unit and source order. Validation verifies timings, shard membership, exact archived recomposition, normalization hashes, both deduplication counts, complete prefix selection, landed ancestry pins, and handoff comparisons.','','Every timing wrapper reports its child’s own exit code and propagates it; shell wrappers also report and propagate their child status. Each child is bounded at 1,740 seconds with at most ten seconds to kill, below 30 minutes. No measured child timed out. Go evidence is named `.go.txt`; logs and JSONL are gzip compressed without changing their bytes. Commands and all analysis/build/shard scripts are retained.','']
stats=[]
for i in range(8):
 x=json.loads((out/'main'/f'shard-{i}.time.json').read_text());assert x['exit_code']==0 and not x['timed_out'] and x['wall_seconds']<1800;stats.append([i,round(x['wall_seconds'],3),round(x['user_seconds'],3),round(x['system_seconds'],3),round(x['peak_rss_kib']/1024,2),x['exit_code']])
lines+=['Each census child’s own measurements (overlapping runs):','',table(['Shard','Wall s','User s','System s','Peak RSS MiB','Child exit'],stats)]
(out/'REPORT.md').write_text('\n'.join(lines).rstrip()+'\n');print('report written; result',r['totals'],'parameter',a['totals'])
